import re

_RANGES = re.compile(r'bytes=(?:(\d+)-(\d+)|(\d+)-|-(\d+))', re.ASCII)


def _digits(s):
    total = 0
    for ch in s:
        total = total * 10 + (ord(ch) - 48)
    return total


def bounds(header, length):
    """Resolve a single byte range against data of the given length.

    Returns the inclusive (start, end) pair, or None when the header is
    malformed or the range cannot be satisfied (416).
    """
    if not isinstance(header, str):
        return None
    m = _RANGES.fullmatch(header)
    if m is None:
        return None
    start_s, end_s, first_s, suffix_s = m.groups()
    if suffix_s is not None:
        n = _digits(suffix_s)
        if n == 0:
            return None
        start = length - n
        if start < 0:
            start = 0
        end = length - 1
        if end < start or start < 0:
            return None
        return start, end
    start = _digits(first_s if first_s is not None else start_s)
    if start > length:
        return None
    if end_s is not None:
        end = _digits(end_s)
    else:
        end = length
    end = min(end, length - 1)
    if start > end:
        return None
    return start, end

